@app.get("/cases/{case_id}/summary")
async def summary(
    case_id: str, session: Session = Depends(get_session)
) -> dict:
    query = select(CaseRow).where(CaseRow.case_id == case_id)
    row = session.execute(query).scalar_one()
    async with httpx.AsyncClient() as client:
        weather = (await client.get(WEATHER_URL)).json()
    return {"title": row.title, "weather": weather}
